/**
 * Nodra methods for the "StockLedger" doctype.
 *
 * Generated by `new:method StockLedger`.
 *
 * Register this module from the app's method bootstrap.
 */
import { Document } from "nodra";
import { ORM } from "nodra/orm/crud";
import { getNodra } from "../nodra-app";

type LocationType = "Factory" | "Warehouse";

type MovementType =
  | "Opening Stock"
  | "Lot Receipt"
  | "Transfer In"
  | "Transfer Out"
  | "Dispatch"
  | "Adjustment In"
  | "Adjustment Out"
  | "Return In"
  | "Return Out";

interface StockLocation {
  location_type: LocationType;
  factory?: string;
  warehouse?: string;
}
interface StockMovement {
  lot: string;
  movement_type: MovementType;
  bags: number;
  quantity: number;

  source?: StockLocation;
  destination?: StockLocation;

  voucher_type: string;
  voucher_no: string;
  voucher_detail_no?: string;

  posting_date?: string;
  remarks?: string;
  against_ledger?: string;
}
function validateLocation(location: StockLocation): void {
  if (location.location_type === "Factory") {
    if (!location.factory || location.warehouse) {
      throw new Error("A valid Factory location is required.");
    }
    return;
  }

  if (location.location_type === "Warehouse") {
    if (!location.warehouse || location.factory) {
      throw new Error("A valid Warehouse location is required.");
    }
    return;
  }

  throw new Error("Invalid stock location.");
}

function validateQuantity(bags: number, quantity: number): void {
  if (
    !Number.isInteger(bags) ||
    bags <= 0 ||
    !Number.isFinite(quantity) ||
    quantity <= 0
  ) {
    throw new Error("Bags and quantity must be positive values.");
  }
}

export async function moveStock(
  orm: ORM,
  movement: StockMovement,
): Promise<void> {
  const {
    lot,
    movement_type,
    bags,
    quantity,
    source,
    destination,
    voucher_type,
    voucher_no,
    voucher_detail_no,
    posting_date,
    remarks,
    against_ledger,
  } = movement;

  validateQuantity(bags, quantity);

  if (!lot || !voucher_type || !voucher_no) {
    throw new Error("Lot and voucher details are required.");
  }

  const inward = ["Opening Stock", "Lot Receipt", "Adjustment In", "Return In"];
  const outward = ["Adjustment Out", "Dispatch", "Return Out"];

  await orm.transaction(async (tx) => {
    // Confirm that the Lot exists.
    await tx.getDoc("Lots", lot);

    // Prevent duplicate posting of the same voucher detail.
    const existing = await tx.getList("StockLedger", {
      filters: {
        voucher_type,
        voucher_no,
        voucher_detail_no: voucher_detail_no ?? "",
        movement_type,
      },
      limit: 1,
    });

    if (existing.length) {
      throw new Error(
        `Stock movement already posted for ${voucher_type} ${voucher_no}.`,
      );
    }

    const nodra = await getNodra();
    const stockLedgerMeta = nodra.registry.get("StockLedger");

    const insertEntry = async (
      location: StockLocation,
      type: MovementType,
      sign: 1 | -1,
    ) => {
      validateLocation(location);

      const doc = new Document(stockLedgerMeta, {
        posting_date: posting_date ?? new Date().toISOString().slice(0, 10),
        lot,
        location_type: location.location_type,
        factory: location.factory ?? "",
        warehouse: location.warehouse ?? "",
        movement_type: type,
        bags: bags * sign,
        quantity: quantity * sign,
        voucher_type,
        voucher_no,
        voucher_detail_no: voucher_detail_no ?? "",
        is_reversal: false,
        against_ledger: against_ledger ?? "",
        remarks: remarks ?? "",
      });

      await tx.insert(doc);
    };

    if (inward.includes(movement_type)) {
      if (!destination) {
        throw new Error("Destination location is required.");
      }

      await insertEntry(destination, movement_type, 1);
      return;
    }

    if (outward.includes(movement_type)) {
      if (!source) {
        throw new Error("Source location is required.");
      }

      await insertEntry(source, movement_type, -1);
      return;
    }

    if (movement_type === "Transfer In" || movement_type === "Transfer Out") {
      throw new Error(
        "Use a Transfer Out movement with both source and destination.",
      );
    }

    throw new Error("Unsupported stock movement type.");
  });
}
